  throw new Error("No text message received.");
}

return [{
  json: {
    ...input,
    userMessage,
    inputType: "text"
  }
}];

const input = $input.first().json;

let parsed;

try {
  parsed = typeof input.output === "string"
    ? JSON.parse(input.output)
    : input.output;
} catch (error) {
  throw new Error("Intent Parser returned invalid JSON.");
}

if (!parsed || typeof parsed !== "object") {
  throw new Error("Intent Parser returned an invalid result.");
}

const allowedIntents = [
  "grocery_budget",
  "grocery_list",
  "price_check",
  "budget_analysis",
  "general_question"
];

if (!allowedIntents.includes(parsed.intent)) {
  throw new Error(`Invalid intent: ${parsed.intent}`);
}

const message = input.userMessage || "";

const budgetMatch = message.match(/₹\s*([\d,]+)/);

const budget =
  parsed.budget !== null && parsed.budget !== undefined
    ? Number(parsed.budget)
    : budgetMatch
      ? Number(budgetMatch[1].replace(/,/g, ""))
      : null;

if (budget !== null && (!Number.isFinite(budget) || budget < 0)) {
  throw new Error("Invalid budget received.");
}

return [{
  json: {
    ...input,
    intent: parsed.intent,
    message: parsed.message || input.userMessage || "",
    budget,
    items: Array.isArray(parsed.items) ? parsed.items : [],
    quantity: Array.isArray(parsed.quantity) ? parsed.quantity : [],
    preferences: Array.isArray(parsed.preferences) ? parsed.preferences : [],
    constraints: Array.isArray(parsed.constraints) ? parsed.constraints : []
  }
}];

