const input = $input.first().json;

const budget = Number(input.budget || 0);
const originalCost = Number(input.originalCost || 0);
const optimizedCost = Number(input.optimizedCost || 0);
const estimatedSavings = Number(input.estimatedSavings || 0);

const remainingBudget = budget - optimizedCost;

return [
  {
    json: {
      ...input,

      finalReport: {
        budget,
        originalCost,
        optimizedCost,
        estimatedSavings,
        remainingBudget,
        budgetStatus: optimizedCost <= budget
          ? "WITHIN_BUDGET"
          : "OVER_BUDGET",
        optimizationStatus: input.optimizationStatus,
        recommendations: input.recommendations || [],
        summary: input.optimizationSummary || ""
      }
    }
  }
];

const input = $input.first().json;

let parsed = {};

if (typeof input.output === "string") {
  try {
    parsed = JSON.parse(input.output);
  } catch (error) {
    parsed = {};
  }
}

return [
  {
    json: {
      ...input,

      finalStatus: parsed.status || "OPTIMIZED",
      finalOriginalCost: Number(parsed.original_cost || 0),
      finalOptimizedCost: Number(parsed.optimized_cost || 0),
      finalSavings: Number(parsed.savings || 0),
      finalRemainingBudget: Number(parsed.remaining_budget || 0),
      finalMessage: parsed.message || "",
      finalRecommendations: parsed.recommendations || []
    }
  }
];

const input = $input.first().json;

// Safely parse the AI output if it arrives as a JSON string
let advisor = {};

try {
  advisor = typeof input.output === "string"
    ? JSON.parse(input.output)
    : (input.output || {});
} catch (error) {
  advisor = {};
}

// Read the financial values
const originalCost = Number(
  input.finalOriginalCost ?? advisor.original_cost ?? 0
);

const optimizedCost = Number(
  input.finalOptimizedCost ?? advisor.optimized_cost ?? 0
);

// Recover the budget.
// Priority: actual user budget -> budget in advisor output ->
// remaining budget + optimized cost.
let budget = Number(
  input.budget ??
  advisor.budget ??
  (
    input.finalRemainingBudget != null
      ? Number(input.finalRemainingBudget) + optimizedCost
      : advisor.remaining_budget != null
        ? Number(advisor.remaining_budget) + optimizedCost
        : NaN
  )
);

// Stop if the budget cannot be recovered.
// Do not silently assume the budget is zero.
if (!Number.isFinite(budget)) {
  throw new Error(
    "Budget is missing. Pass the user's budget into this node from an upstream node."
  );
}

// Calculate all financial values using JavaScript
const savings = originalCost - optimizedCost;
const remainingBudget = budget - optimizedCost;

let budgetStatus;

if (remainingBudget > 0) {
  budgetStatus = "WITHIN_BUDGET";
} else if (remainingBudget === 0) {
  budgetStatus = "ON_BUDGET";
} else {
  budgetStatus = "OVER_BUDGET";
}

// Read recommendations
const recommendations =
  input.finalRecommendations ??
  advisor.recommendations ??
  [];

// Remove quantity-reduction suggestions when the optimized
// grocery cost is already within the user's budget.
const filteredRecommendations = recommendations.filter(rec => {
  const item = String(
    typeof rec === "string" ? rec : rec.item || ""
  ).toLowerCase();

  if (
    remainingBudget >= 0 &&
    (
      item.includes("optional") ||
      item.includes("quantity reduction")
    )
  ) {
    return false;
  }

  return true;
});

// Format recommendations
const recommendationText = filteredRecommendations
  .map((rec, index) => {
    if (typeof rec === "string") {
      return `${index + 1}. ${rec}`;
    }

    return `${index + 1}. *${rec.item || "General recommendation"}*

Action: ${rec.action || "Not specified"}

Reason: ${rec.reason || "Not specified"}

Estimated Savings: ₹${Number(
      rec.estimated_savings || 0
    ).toLocaleString("en-IN")}`;
  })
  .join("\n\n");

// Currency formatter
const formatINR = value =>
  `₹${Number(value).toLocaleString("en-IN")}`;

// Build Telegram message
const message = `🛒 *Smart Grocery Budget Report*

💰 *Total Budget:* ${formatINR(budget)}

📊 *Original Cost:* ${formatINR(originalCost)}

✨ *Optimized Cost:* ${formatINR(optimizedCost)}

💸 *Estimated Savings:* ${formatINR(savings)}

💵 *Remaining Budget:* ${formatINR(remainingBudget)}

${budgetStatus === "OVER_BUDGET" ? "⚠️" : "✅"} *Status:* ${budgetStatus}

📝 *Summary:*
${input.finalMessage || advisor.message || "Optimization completed."}

💡 *Recommendations:*
${recommendationText || "No recommendations available."}

⚠️ Prices are estimates, not verified live market prices.`;

// Return final data
return [
  {
    json: {
      ...input,
      budget,
      finalOriginalCost: originalCost,
      finalOptimizedCost: optimizedCost,
      finalSavings: savings,
      finalRemainingBudget: remainingBudget,
      finalStatus: budgetStatus,
      finalRecommendations: filteredRecommendations,
      telegramMessage: message
    }
  }
];

