}

const message = `⚠️ *Grocery Budget Recovery Plan*

💰 *Available Budget:* ₹${input.recoveryTargetBudget}

📊 *Current Cost:* ₹${input.recoveryCurrentCost}

🎯 *Revised Cost:* ₹${input.recoveryRevisedCost}

💸 *Additional Savings Needed:* ₹${input.additionalSavingsNeeded}

📝 *Summary:*
${input.recoverySummary}

💡 *Recovery Recommendations:*
${recommendationText}`;

return [
  {
    json: {
      ...input,
      recoveryTelegramMessage: message
    }
  }
];

