const remainingBudget = Number(input.remainingBudget || 0);

const recommendations = input.recommendations || [];

let message = `🛒 *Grocery Budget Plan*\n\n`;

message += `💰 *Total Budget:* ₹${budget.toLocaleString("en-IN")}\n`;
message += `📊 *Allocated:* ₹${totalAllocated.toLocaleString("en-IN")}\n`;
message += `💵 *Remaining:* ₹${remainingBudget.toLocaleString("en-IN")}\n\n`;

