  message += `📌 *Recommendations:*\n\n`;

  recommendations.forEach((rec, index) => {
    message += `${index + 1}. *${rec.category || "General"}*\n`;
    message += `   ${rec.recommendation || ""}\n`;

    if (rec.potential_saving) {
      message += `   💡 Potential Saving: ₹${Number(
        rec.potential_saving
      ).toLocaleString("en-IN")}\n`;
    }

    message += `\n`;
  });
}

if (input.recommendationSummary) {
  message += `📝 *Summary:*\n${input.recommendationSummary}\n`;
}

return [
  {
    json: {
      ...input,
      telegramMessage: message.trim()
    }
