    "en-IN"
  )} - ₹${maximum.toLocaleString("en-IN")} / ${unit}\n`;
}

message += `\n⚠️ *Price Type:* ${input.priceType || "estimated"}\n`;

if (input.priceAdvice) {
  message += `\n💡 *Advice:*\n${input.priceAdvice}`;
