  input.analysisRequest ||
  input.message ||
  ""
);

const numbers = [...message.matchAll(/(?:₹|Rs\.?|INR)?\s*([\d,]+(?:\.\d+)?)/gi)]
  .map(m => Number(m[1].replace(/,/g, "")))
  .filter(n => !isNaN(n));

let budget = 0;
let spent = 0;

const budgetMatch = message.match(
  /budget\s*(?:is|of|:)?\s*(?:₹|Rs\.?|INR)?\s*([\d,]+)/i
);

const spentMatch = message.match(
  /spent\s*(?:₹|Rs\.?|INR)?\s*([\d,]+)/i
);

if (budgetMatch) {
  budget = Number(budgetMatch[1].replace(/,/g, ""));
}

if (spentMatch) {
  spent = Number(spentMatch[1].replace(/,/g, ""));
}

return [
  {
    json: {
      ...input,
      intent: "budget_analysis",
      budget,
      spent,
      currency: "INR",
      analysisRequest: message
    }
  }
];

