  !Number.isFinite(budget) ||
  !Number.isFinite(spent) ||
  budget <= 0 ||
  spent < 0
) {
  throw new Error("Please provide a valid budget and spending amount.");
}

const remainingBudget = budget - spent;
const spendingPercentage = Number(
  ((spent / budget) * 100).toFixed(2)
);

